PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','staff')),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS vehicles(id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,brand TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('Bike','Scooter','Car')),registration TEXT UNIQUE NOT NULL,rate INTEGER NOT NULL CHECK(rate>0),deposit INTEGER NOT NULL DEFAULT 0 CHECK(deposit>=0),fuel TEXT NOT NULL,transmission TEXT NOT NULL,seats INTEGER NOT NULL,engine TEXT NOT NULL,image TEXT NOT NULL,description TEXT NOT NULL,odometer INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'Available' CHECK(status IN ('Available','Maintenance','Inactive')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT UNIQUE NOT NULL,email TEXT NOT NULL DEFAULT '',verified INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bookings(id TEXT PRIMARY KEY,reference TEXT UNIQUE NOT NULL,access_hash TEXT NOT NULL,customer_id TEXT NOT NULL REFERENCES customers(id),vehicle_id TEXT NOT NULL REFERENCES vehicles(id),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,hours INTEGER NOT NULL,rate INTEGER NOT NULL,base INTEGER NOT NULL,tax INTEGER NOT NULL,deposit INTEGER NOT NULL,extra INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL CHECK(status IN ('confirmed','active','inspecting','completed','cancelled')),source TEXT NOT NULL CHECK(source IN ('Website','Phone','Walk-in')),notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,CHECK(ends_at>starts_at));
CREATE INDEX IF NOT EXISTS booking_availability ON bookings(vehicle_id,status,starts_at,ends_at);
CREATE INDEX IF NOT EXISTS booking_customer ON bookings(customer_id);
CREATE TABLE IF NOT EXISTS rentals(id TEXT PRIMARY KEY,booking_id TEXT UNIQUE NOT NULL REFERENCES bookings(id),pickup_at TEXT NOT NULL,return_at TEXT,pickup_staff TEXT NOT NULL REFERENCES users(id),return_staff TEXT REFERENCES users(id),pickup_odometer INTEGER NOT NULL,return_odometer INTEGER,late_minutes INTEGER NOT NULL DEFAULT 0,late_charge INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS inspections(id TEXT PRIMARY KEY,rental_id TEXT NOT NULL REFERENCES rentals(id),type TEXT NOT NULL CHECK(type IN ('pickup','return')),fuel TEXT NOT NULL,condition TEXT NOT NULL,notes TEXT NOT NULL,staff_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES bookings(id),amount INTEGER NOT NULL CHECK(amount>0),purpose TEXT NOT NULL CHECK(purpose IN ('rental','deposit')),method TEXT NOT NULL CHECK(method IN ('Cash','UPI','Card')),note TEXT NOT NULL DEFAULT '',staff_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS refunds(id TEXT PRIMARY KEY,payment_id TEXT NOT NULL REFERENCES payments(id),amount INTEGER NOT NULL CHECK(amount>0),reason TEXT NOT NULL,staff_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS maintenance(id TEXT PRIMARY KEY,vehicle_id TEXT NOT NULL REFERENCES vehicles(id),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,reason TEXT NOT NULL,resolved INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,CHECK(ends_at>starts_at));
CREATE INDEX IF NOT EXISTS maintenance_window ON maintenance(vehicle_id,starts_at,ends_at);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),action TEXT NOT NULL,entity_id TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS booking_contacts(booking_id TEXT PRIMARY KEY REFERENCES bookings(id),name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',verified INTEGER NOT NULL DEFAULT 0);
